        var seat = position switch
        {
            SeatPosition.Driver => seats.Driver,
            SeatPosition.Copilot => seats.Copilot,
            SeatPosition.RearLeft => seats.RearLeft,
            SeatPosition.RearRight => seats.RearRight,
            _ => throw new DataException($"{position} is not a valid SeatPosition"),
